export async function searchMFSchemes(query: string) {
  if (!query || query.length < 2) return [];
  const userAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";
  const qLower = query.toLowerCase();
  const encodedQuery = encodeURIComponent(query);

  const seenCodes = new Set<string>();
  const combinedResults: { schemeCode: string; schemeName: string }[] = [];

  const addResults = (list: { schemeCode?: string; schemeName?: string }[]) => {
    for (const item of list) {
      if (item.schemeCode && item.schemeName) {
        const code = item.schemeCode.trim();
        if (!seenCodes.has(code)) {
          seenCodes.add(code);
          combinedResults.push({ schemeCode: code, schemeName: item.schemeName.trim() });
        }
      }
    }
  };

  // Fetch concurrently from MFAPI.in, Groww API, and AMFI Official NAV text
  const apiResults = await Promise.allSettled([
    // 1. api.mfapi.in API
    fetch(`https://api.mfapi.in/mf/search?q=${encodedQuery}`, {
      cache: "no-store",
      headers: { "User-Agent": userAgent },
      signal: AbortSignal.timeout(4000)
    }).then(async (res) => {
      if (!res.ok) return [];
      const data = await res.json();
      return (data || []).map((s: { schemeCode?: number; schemeName: string }) => ({
        schemeCode: s.schemeCode?.toString(),
        schemeName: s.schemeName
      }));
    }),

    // 2. Groww MF Search API
    fetch(`https://groww.in/v1/api/search/v1/derived/scheme?availableForInvestment=true&docType=scheme&q=${encodedQuery}`, {
      cache: "no-store",
      headers: { "User-Agent": userAgent },
      signal: AbortSignal.timeout(4000)
    }).then(async (res) => {
      if (!res.ok) return [];
      const data = await res.json();
      const items = data?.content ?? [];
      return items.map((s: { scheme_code?: string; scheme_name?: string; fund_name?: string }) => ({
        schemeCode: s.scheme_code?.toString(),
        schemeName: s.scheme_name || s.fund_name
      }));
    }),

    // 3. AMFI India Official NAV dataset
    getAmfiNavText().then((text) => {
      if (!text) return [];
      const lines = text.split("\n");
      const list = [];
      for (const line of lines) {
        if (line.includes(";")) {
          const parts = line.split(";");
          if (parts.length >= 4 && parts[3].toLowerCase().includes(qLower)) {
            list.push({ schemeCode: parts[0].trim(), schemeName: parts[3].trim() });
            if (list.length >= 15) break;
          }
        }
      }
      return list;
    })
  ]);

  for (const res of apiResults) {
    if (res.status === "fulfilled" && Array.isArray(res.value)) {
      addResults(res.value);
    }
  }

  if (combinedResults.length > 0) {
    return combinedResults.slice(0, 20);
  }

  // Fallback to local popular funds
  return POPULAR_FUNDS.filter(f => f.schemeName.toLowerCase().includes(qLower) || f.schemeCode.includes(qLower));
}

export async function fetchLiveMFNAV(schemeCode: string) {
  const now = Date.now();
  const cached = navCache.get(schemeCode);
  if (cached && (now - cached.timestamp < NAV_CACHE_TTL)) {
    return { nav: cached.nav, previousNav: cached.previousNav };
  }

  const userAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";
  
  // Try api.mfapi.in first
  try {
    const res = await fetch(`https://api.mfapi.in/mf/${schemeCode}`, { 
      cache: "no-store",
      headers: { "User-Agent": userAgent },
      signal: AbortSignal.timeout(6000)
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.data && data.data.length > 0) {
        const currentNav = parseFloat(data.data[0].nav);
        const previousNav = data.data.length > 1 ? parseFloat(data.data[1].nav) : undefined;
        
        navCache.set(schemeCode, { nav: currentNav, previousNav, timestamp: now });
        return { nav: currentNav, previousNav };
      }
    }
  } catch (err) {
    console.warn(`MFAPI NAV failed for ${schemeCode}, trying Groww fallback`, err);
  }
  
  // Try Groww MF API fallback
  try {
    const res = await fetch(`https://groww.in/v1/api/search/v1/derived/scheme?availableForInvestment=true&docType=scheme&q=${schemeCode}`, {
      cache: "no-store",
      headers: { "User-Agent": userAgent },
      signal: AbortSignal.timeout(5000)
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.content && data.content.length > 0) {
        const matched = data.content.find((s: any) => s.scheme_code === schemeCode);
        if (matched && typeof matched.nav === "number") {
          navCache.set(schemeCode, { nav: matched.nav, timestamp: now });
          return { nav: matched.nav };
        }
      }
    }
  } catch (err) {
    console.warn(`Groww NAV failed for ${schemeCode}, trying AMFI fallback`, err);
  }

  // Try AMFI fallback
  try {
    const text = await getAmfiNavText();
    if (text) {
      const lines = text.split("\n");
      for (const line of lines) {
        if (line.startsWith(`${schemeCode};`)) {
          const parts = line.split(";");
          const currentNav = parseFloat(parts[4].trim());
          if (!isNaN(currentNav)) {
            navCache.set(schemeCode, { nav: currentNav, timestamp: now });
            return { nav: currentNav };
          }
        }
      }
    }
  } catch (err) {
    console.error("AMFI fallback search failed", err);
  }
  
  return null;
}

import { MutualFundInvestmentSchema } from "@/lib/validations";

export async function recordMFInvestment(data: {
  fund_name: string;
  scheme_code: string;
  units: number;
  nav: number;
  investment_type: string;
  category: string;
  amc_name: string;
  date: string;
  account_id: string;
  stamp_duty: number;
  trade_type?: "buy" | "sell";
}) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Unauthorized" };

    const validation = MutualFundInvestmentSchema.safeParse(data);
    if (!validation.success) {
      return { error: validation.error.issues[0]?.message || "Invalid mutual fund payload" };
    }
    const validData = validation.data;

    const cleanAccountId = validData.account_id && 
      validData.account_id.trim().length > 0 && 
      validData.account_id !== "null" && 
      validData.account_id !== "undefined" 
        ? validData.account_id 
        : null;

    const rpc = supabase.rpc.bind(supabase) as unknown as (
      fn: "record_mf_investment_v4",
      args: {
        p_user_id: string;
        p_fund_name: string;
        p_scheme_code: string;
        p_units: number;
        p_nav: number;
        p_investment_type: string;
        p_category: string;
        p_amc_name: string;
        p_date: string;
        p_account_id: string | null;
        p_stamp_duty: number;
        p_trade_type: "buy" | "sell";
      }
    ) => Promise<{ data: MutualFundRpcResult; error: { message: string } | null }>;

    const cleanDate = parseToISODate(data.date);

    const { data: res, error } = await rpc("record_mf_investment_v4", {
      p_user_id: user.id,
      p_fund_name: data.fund_name,
      p_scheme_code: data.scheme_code,
      p_units: data.units,
      p_nav: data.nav,
      p_investment_type: data.investment_type,
      p_category: data.category,
      p_amc_name: data.amc_name,
      p_date: cleanDate,
      p_account_id: cleanAccountId,
      p_stamp_duty: data.stamp_duty,
      p_trade_type: data.trade_type || "buy"
    });

    if (error) return { error: getFriendlyErrorMessage(error) };
    revalidatePath("/dashboard/mutual-funds");
    revalidatePath("/dashboard/ledger");
    revalidatePath("/dashboard");
    return res;
  } catch (err) {
    console.error("Error in recordMFInvestment:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function updateMFHolding(id: string, data: {
  fund_name?: string;
  amc_name?: string;
  scheme_code?: string;
  fund_symbol?: string;
  units?: number;
  avg_nav?: number;
  current_nav?: number;
  previous_nav?: number;
  category?: string;
  investment_type?: string;
}) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Unauthorized" };

    const payload: Record<string, unknown> = { updated_at: new Date().toISOString() };
    if (data.fund_name !== undefined) payload.fund_name = data.fund_name;
    if (data.amc_name !== undefined) payload.amc_name = data.amc_name;
    if (data.scheme_code !== undefined) payload.scheme_code = data.scheme_code;
    if (data.fund_symbol !== undefined) payload.fund_symbol = data.fund_symbol;
    if (data.units !== undefined) payload.units = data.units;
    if (data.avg_nav !== undefined) payload.avg_nav = data.avg_nav;
    if (data.current_nav !== undefined) payload.current_nav = data.current_nav;
    if (data.previous_nav !== undefined) payload.previous_nav = data.previous_nav;
    if (data.category !== undefined) payload.category = data.category;
    if (data.investment_type !== undefined) payload.investment_type = data.investment_type;

    const { error } = await supabase
      .from("mutual_funds")
      .update(payload as any)
      .eq("id", id)
      .eq("user_id", user.id);

    if (error) return { error: getFriendlyErrorMessage(error) };

    revalidatePath("/dashboard/mutual-funds");
    return { success: true, message: "M F Holding updated successfully" };
  } catch (err) {
    console.error("Error in updateMFHolding:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function importCASPortfolio(items: Array<{
  assetClass: "mutual_fund" | "stock";
  name: string;
  symbolOrSchemeCode?: string;
  unitsOrQuantity: number;
  currentNavOrPrice: number;
}>) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: "Unauthorized" };

    if (!items || items.length === 0) return { error: "No portfolio items selected for import" };

    let importedMf = 0;
    let importedStock = 0;

    for (const item of items) {
      if (item.assetClass === "mutual_fund") {
        await supabase.from("mutual_funds").insert({
          user_id: user.id,
          fund_name: item.name,
          scheme_code: item.symbolOrSchemeCode || null,
          fund_symbol: item.symbolOrSchemeCode || null,
          units: item.unitsOrQuantity,
          avg_nav: item.currentNavOrPrice,
          current_nav: item.currentNavOrPrice,
          category: "Direct Growth",
        });
        importedMf++;
      } else {
        await supabase.from("investments").insert({
          user_id: user.id,
          name: item.name,
          type: "stock",
          symbol: item.symbolOrSchemeCode || item.name.substring(0, 10).toUpperCase(),
          quantity: item.unitsOrQuantity,
          buy_price: item.currentNavOrPrice,
          current_price: item.currentNavOrPrice,
        });
        importedStock++;
      }
    }

    await supabase.from("ledger_logs").insert({
      user_id: user.id,
      action_type: "CAS_IMPORT",
      details: `CAS Portfolio Import: ${importedMf} Mutual Funds and ${importedStock} Stocks imported.`,
      source_type: "cas_import",
    });

    revalidatePath("/dashboard/mutual-funds");
    revalidatePath("/dashboard/stocks");
    revalidatePath("/dashboard");
    return {
      success: true,
      message: `Successfully imported ${importedMf} Mutual Funds and ${importedStock} Stocks!`,
    };
  } catch (err) {
    console.error("Error in importCASPortfolio:", err);
    return { error: getFriendlyErrorMessage(err) };
  }
}

export async function syncMFNavsAction() {
  try {
    const { syncAllMutualFundPrices } = await import("@/lib/sync-mf");
    const res = await syncAllMutualFundPrices();
    revalidatePath("/dashboard/mutual-funds");
    revalidatePath("/dashboard");
    return { success: true, message: `Successfully synced live NAVs for ${res.updatedCount} mutual funds!` };
  } catch (err) {
    return { error: getFriendlyErrorMessage(err) };
  }
}

